-- Transactional per-conversation projections. No message bodies are duplicated.
CREATE TABLE mailbox_threads(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,domain_scope TEXT NOT NULL,thread_id TEXT NOT NULL,v_inbox INTEGER NOT NULL DEFAULT 0,v_inbox_unread INTEGER NOT NULL DEFAULT 0,v_starred INTEGER NOT NULL DEFAULT 0,v_drafts INTEGER NOT NULL DEFAULT 0,v_sent INTEGER NOT NULL DEFAULT 0,v_trash INTEGER NOT NULL DEFAULT 0,v_all INTEGER NOT NULL DEFAULT 0,v_spam INTEGER NOT NULL DEFAULT 0,live_at TEXT,trash_at TEXT,draft_at TEXT,live_pin INTEGER,trash_pin INTEGER,draft_pin INTEGER,PRIMARY KEY(user_id,domain_scope,thread_id));
CREATE INDEX mailbox_threads_inbox_live ON mailbox_threads(user_id,domain_scope,v_inbox,live_pin DESC,live_at DESC);
CREATE INDEX mailbox_threads_inbox_unread_live ON mailbox_threads(user_id,domain_scope,v_inbox_unread,live_pin DESC,live_at DESC);
CREATE INDEX mailbox_threads_starred_live ON mailbox_threads(user_id,domain_scope,v_starred,live_pin DESC,live_at DESC);
CREATE INDEX mailbox_threads_drafts_draft ON mailbox_threads(user_id,domain_scope,v_drafts,draft_pin DESC,draft_at DESC);
CREATE INDEX mailbox_threads_sent_live ON mailbox_threads(user_id,domain_scope,v_sent,live_pin DESC,live_at DESC);
CREATE INDEX mailbox_threads_trash_trash ON mailbox_threads(user_id,domain_scope,v_trash,trash_pin DESC,trash_at DESC);
CREATE INDEX mailbox_threads_all_live ON mailbox_threads(user_id,domain_scope,v_all,live_pin DESC,live_at DESC);
CREATE INDEX mailbox_threads_spam_live ON mailbox_threads(user_id,domain_scope,v_spam,live_pin DESC,live_at DESC);
INSERT INTO mailbox_threads(user_id,domain_scope,thread_id,v_inbox,v_inbox_unread,v_starred,v_drafts,v_sent,v_trash,v_all,v_spam,live_at,trash_at,draft_at,live_pin,trash_pin,draft_pin) SELECT user_id,domain_scope,COALESCE(thread_id,id),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' AND is_read=0 THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND is_starred=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND direction='outbound' AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NOT NULL THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NOT NULL THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN is_pinned END),MAX(CASE WHEN deleted_at IS NOT NULL THEN is_pinned END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN is_pinned END) FROM (SELECT *,'' AS domain_scope FROM emails WHERE 1=1 UNION ALL SELECT *,COALESCE(domain_id,'__none__') AS domain_scope FROM emails WHERE 1=1) GROUP BY user_id,domain_scope,COALESCE(thread_id,id);
CREATE TRIGGER mailbox_threads_insert AFTER INSERT ON emails BEGIN
DELETE FROM mailbox_threads WHERE user_id=NEW.user_id AND thread_id=COALESCE(NEW.thread_id,NEW.id);
INSERT INTO mailbox_threads(user_id,domain_scope,thread_id,v_inbox,v_inbox_unread,v_starred,v_drafts,v_sent,v_trash,v_all,v_spam,live_at,trash_at,draft_at,live_pin,trash_pin,draft_pin) SELECT user_id,domain_scope,COALESCE(thread_id,id),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' AND is_read=0 THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND is_starred=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND direction='outbound' AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NOT NULL THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NOT NULL THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN is_pinned END),MAX(CASE WHEN deleted_at IS NOT NULL THEN is_pinned END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN is_pinned END) FROM (SELECT *,'' AS domain_scope FROM emails WHERE user_id=NEW.user_id AND COALESCE(thread_id,id)=COALESCE(NEW.thread_id,NEW.id) UNION ALL SELECT *,COALESCE(domain_id,'__none__') AS domain_scope FROM emails WHERE user_id=NEW.user_id AND COALESCE(thread_id,id)=COALESCE(NEW.thread_id,NEW.id)) GROUP BY user_id,domain_scope,COALESCE(thread_id,id);
END;
CREATE TRIGGER mailbox_threads_delete AFTER DELETE ON emails BEGIN
DELETE FROM mailbox_threads WHERE user_id=OLD.user_id AND thread_id=COALESCE(OLD.thread_id,OLD.id);
INSERT INTO mailbox_threads(user_id,domain_scope,thread_id,v_inbox,v_inbox_unread,v_starred,v_drafts,v_sent,v_trash,v_all,v_spam,live_at,trash_at,draft_at,live_pin,trash_pin,draft_pin) SELECT user_id,domain_scope,COALESCE(thread_id,id),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' AND is_read=0 THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND is_starred=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND direction='outbound' AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NOT NULL THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NOT NULL THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN is_pinned END),MAX(CASE WHEN deleted_at IS NOT NULL THEN is_pinned END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN is_pinned END) FROM (SELECT *,'' AS domain_scope FROM emails WHERE user_id=OLD.user_id AND COALESCE(thread_id,id)=COALESCE(OLD.thread_id,OLD.id) UNION ALL SELECT *,COALESCE(domain_id,'__none__') AS domain_scope FROM emails WHERE user_id=OLD.user_id AND COALESCE(thread_id,id)=COALESCE(OLD.thread_id,OLD.id)) GROUP BY user_id,domain_scope,COALESCE(thread_id,id);
END;
CREATE TRIGGER mailbox_threads_update AFTER UPDATE OF user_id,thread_id,domain_id,deleted_at,is_archived,is_spam,is_read,is_starred,is_pinned,status,created_at ON emails WHEN OLD.user_id IS NOT NEW.user_id OR OLD.thread_id IS NOT NEW.thread_id OR OLD.domain_id IS NOT NEW.domain_id OR OLD.deleted_at IS NOT NEW.deleted_at OR OLD.is_archived IS NOT NEW.is_archived OR OLD.is_spam IS NOT NEW.is_spam OR OLD.is_read IS NOT NEW.is_read OR OLD.is_starred IS NOT NEW.is_starred OR OLD.is_pinned IS NOT NEW.is_pinned OR OLD.status IS NOT NEW.status OR OLD.created_at IS NOT NEW.created_at BEGIN
DELETE FROM mailbox_threads WHERE user_id=OLD.user_id AND thread_id=COALESCE(OLD.thread_id,OLD.id) AND (OLD.user_id IS NOT NEW.user_id OR COALESCE(OLD.thread_id,OLD.id) IS NOT COALESCE(NEW.thread_id,NEW.id));
INSERT INTO mailbox_threads(user_id,domain_scope,thread_id,v_inbox,v_inbox_unread,v_starred,v_drafts,v_sent,v_trash,v_all,v_spam,live_at,trash_at,draft_at,live_pin,trash_pin,draft_pin) SELECT user_id,domain_scope,COALESCE(thread_id,id),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' AND is_read=0 THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND is_starred=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND direction='outbound' AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NOT NULL THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NOT NULL THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN is_pinned END),MAX(CASE WHEN deleted_at IS NOT NULL THEN is_pinned END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN is_pinned END) FROM (SELECT *,'' AS domain_scope FROM emails WHERE user_id=OLD.user_id AND COALESCE(thread_id,id)=COALESCE(OLD.thread_id,OLD.id) AND (OLD.user_id IS NOT NEW.user_id OR COALESCE(OLD.thread_id,OLD.id) IS NOT COALESCE(NEW.thread_id,NEW.id)) UNION ALL SELECT *,COALESCE(domain_id,'__none__') AS domain_scope FROM emails WHERE user_id=OLD.user_id AND COALESCE(thread_id,id)=COALESCE(OLD.thread_id,OLD.id) AND (OLD.user_id IS NOT NEW.user_id OR COALESCE(OLD.thread_id,OLD.id) IS NOT COALESCE(NEW.thread_id,NEW.id))) GROUP BY user_id,domain_scope,COALESCE(thread_id,id);
DELETE FROM mailbox_threads WHERE user_id=NEW.user_id AND thread_id=COALESCE(NEW.thread_id,NEW.id);
INSERT INTO mailbox_threads(user_id,domain_scope,thread_id,v_inbox,v_inbox_unread,v_starred,v_drafts,v_sent,v_trash,v_all,v_spam,live_at,trash_at,draft_at,live_pin,trash_pin,draft_pin) SELECT user_id,domain_scope,COALESCE(thread_id,id),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_archived=0 AND is_spam=0 AND direction='inbound' AND is_read=0 THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND is_starred=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND direction='outbound' AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NOT NULL THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=0 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND is_spam=1 AND (status IS NULL OR status<>'draft') THEN 1 ELSE 0 END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NOT NULL THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN datetime(created_at) END),MAX(CASE WHEN deleted_at IS NULL AND (status IS NULL OR status<>'draft') THEN is_pinned END),MAX(CASE WHEN deleted_at IS NOT NULL THEN is_pinned END),MAX(CASE WHEN deleted_at IS NULL AND status='draft' THEN is_pinned END) FROM (SELECT *,'' AS domain_scope FROM emails WHERE user_id=NEW.user_id AND COALESCE(thread_id,id)=COALESCE(NEW.thread_id,NEW.id) UNION ALL SELECT *,COALESCE(domain_id,'__none__') AS domain_scope FROM emails WHERE user_id=NEW.user_id AND COALESCE(thread_id,id)=COALESCE(NEW.thread_id,NEW.id)) GROUP BY user_id,domain_scope,COALESCE(thread_id,id);
